'use strict';
const M=IntroducerModel, KEY='finsyndeo-whole-review-introducer-phase1-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}const store=new M.Store(saved?.state), ui=saved?.ui||{view:'dashboard',intro:'I-A',adminIntro:'I-A',provider:'FS-003',currency:'EUR',drafts:{}};
ui.drafts=ui.drafts||{};const params=new URLSearchParams(location.search);let role=ui.role||'introducer';store.login(role,role==='admin'?'SOPHIMA Admin':role==='introducer'?ui.intro:'SAMPLE Applicant');if(params.has('ref')){role='applicant';store.login('applicant','SAMPLE Applicant');ui.view='referral';}
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,c=ui.currency)=>new Intl.NumberFormat('en-GB',{style:'currency',currency:c}).format((n||0)/100), percent=n=>(n/100).toFixed(n%100?2:0)+'%', date=x=>x?x.slice(0,10):'—';
const client=id=>store.s.clients.find(c=>c.id===id)?.name||id, provider=id=>store.s.providers.find(p=>p.id===id), intro=id=>store.intro(id), value=n=>(n/100).toFixed(2);
let countries=window.INTRODUCER_COUNTRIES||[];
function countryOptions(selected='CY'){const basic=[['CY','Cyprus'],['GB','United Kingdom'],['MT','Malta'],['IE','Ireland'],['DE','Germany'],['US','United States'],['CA','Canada']];const known=Object.fromEntries(basic.map(([c,n])=>[n,c]));const list=countries.length?countries.map(c=>typeof c==='string'?[known[c]||c,c]:[c.code||c.id,c.name]):basic;return list.map(([code,name])=>`<option value="${h(code)}" ${code===selected?'selected':''}>${h(name)}</option>`).join('');}
const options=(a,v)=>a.map(x=>`<option value="${h(x)}" ${x===v?'selected':''}>${h(TAXES[x]||({entity:'A legal entity',individual:'An individual',financial_institution:'A financial institution'})[x]||x)}</option>`).join('');
const pill=(x,good=false)=>`<span class="pill ${good?'ok':''}">${h(x)}</span>`;
const field=(label,name,type='text',v='',required=false,extra='')=>`<label class="field"><span>${label}</span><input name="${h(name)}" type="${type}" value="${h(v)}" ${required?'required':''} ${extra}></label>`;
const select=(label,name,a,v='',extra='')=>`<label class="field"><span>${label}</span><select name="${h(name)}" ${extra}>${options(a,v)}</select></label>`;
const check=(label,name,checked=false)=>`<label class="checkline"><input type="checkbox" name="${h(name)}" ${checked?'checked':''}><span>${label}</span></label>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map((x,n)=>`<td data-label="${h(heads[n])}">${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}" class="empty">No records in this view.</td></tr>`}</tbody></table></div>`;
const metric=(label,val,note='')=>`<div class="metric"><span>${label}</span><b>${val}</b>${note?`<small>${note}</small>`:''}</div>`;
function notify(s,bad=false){const e=$('#message');e.hidden=false;e.className=bad?'error':'';e.textContent=s;e.scrollIntoView({block:'nearest',behavior:'smooth'});}
function save(){ui.role=role;try{localStorage.setItem(KEY,JSON.stringify({state:store.s,ui}));}catch{notify('This browser cannot save more sample documents. Download your review files and reset the sample, or use smaller files.',true);}}
function run(fn,success){try{const result=fn();save();render();notify(success||'Sample record saved.');return result;}catch(e){save();notify(e.message,true);return false;}}
function view(name){capture();ui.view=name;save();render();window.scrollTo({top:0,behavior:'smooth'});}
function draftKey(){return [role,ui.intro,ui.view,ui.provider,ui.adminIntro,ui.currency].join(':');}
function capture(){const vals={};$$('form[data-draft] [name]').forEach(e=>{if(e.type==='file')return;vals[e.name]=e.type==='checkbox'?e.checked:e.value;});if(Object.keys(vals).length)ui.drafts[draftKey()]=vals;}
function restore(){const d=ui.drafts[draftKey()]||{};$$('form[data-draft] [name]').forEach(e=>{if(e.type==='file'||!(e.name in d))return;if(e.type==='checkbox')e.checked=d[e.name];else e.value=d[e.name];});const effective=$('#rate-form [name=effective]');if(effective&&Date.parse(effective.value+'Z')<Date.parse(store.now()))effective.value=store.now().slice(0,19);}
function data(f){const o={};for(const e of f.elements){if(e.name)o[e.name]=e.type==='checkbox'?e.checked:e.value;}return o;}
async function fileDoc(input,owner,category,status='Uploaded'){const f=input.files?.[0];if(!f)throw Error('Please choose a file to upload through the portal.');if(f.size>2*1024*1024)throw Error('Use a sample file of 2 MB or less. Production limits will be configured separately.');if(!/\.(pdf|png|jpg|jpeg|txt|csv|docx)$/i.test(f.name))throw Error('Choose a PDF, image, Word, CSV or text sample document.');const body=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f);});return store.addDoc({owner,name:f.name,category,status,version:'1',body,mime:f.type||'application/octet-stream',dataURL:true});}
function downloadDoc(id){let d;try{d=store.documentView(id);if(d.dataURL){const a=document.createElement('a');a.href=d.body;a.download=d.name;a.click();}else{download(d.name.endsWith('.txt')?d.name:d.name+'.txt',d.body,'text/plain');}}catch(e){notify(e.message,true);}}
function download(name,body,mime='text/csv'){const u=URL.createObjectURL(new Blob([body],{type:mime})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);}
function csv(rows){return rows.map(row=>row.map(x=>{let s=String(x??'');if(typeof x==='string'&&!/^-?\d+(\.\d+)?$/.test(s)&&/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
function currencySelector(){return `<label>Statement currency <select id="currency" aria-label="Statement currency">${options(['EUR','GBP','USD','CHF'],ui.currency)}</select></label>`;}
function render(){const admin=role==='admin',anonymous=['login','referral','confirm'].includes(ui.view);$('#message').hidden=true;$('#session-bar').innerHTML=`<span>${admin?'SOPHIMA Admin · sample session':role==='introducer'?h(intro(ui.intro).name)+' · invited introducer': 'Applicant · sample session'}<br><small>Sample clock: ${h(store.now().replace('T',' ').replace('.000Z',' UTC'))}</small></span>${role==='introducer'?currencySelector():''}`;
const nav=admin?[['overview','Overview'],['profiles','Introducers'],['providers','Provider access'],['referrals','Clients & relationships'],['commissions','Provider commissions'],['invoices','Invoices & payments'],['reports','Accounting reports'],['audit','Audit trail']]:[['dashboard','Dashboard'],['referrals','My referrals'],['ledger','My commissions'],['invoice','Upload invoice'],['invoices','Payments & reconciliation'],['documents','My Documents']];$('#nav').innerHTML=anonymous?'':nav.map(([id,label])=>`<button data-view="${id}" ${ui.view===id?'aria-current="page"':''}>${label}</button>`).join('');
const page=({login:loginPage,referral:referralPage,confirm:confirmPage,overview:overviewPage,profiles:profilePage,providers:providersPage,referrals:referralsPage,commissions:commissionsPage,ledger:ledgerPage,invoice:invoicePage,invoices:invoicesPage,documents:documentsPage,reports:reportsPage,audit:auditPage,dashboard:dashboardPage})[ui.view]||dashboardPage;$('#content').innerHTML=page();restore();bind();refreshCalculations();}
function dashboardPage(){const x=store.external(ui.intro),b=store.balances(ui.intro,ui.currency);return `<div class="eyebrow">Introducer dashboard</div><h1>Welcome, ${h(x.profile.name)}</h1><p class="lead">Your referrals, commission statement and payments in one place.</p><div class="metrics">${metric('Current commission rate',percent(x.profile.rate))}${metric('Qualified successful clients',x.profile.qualified,'Distinct clients, including past successes')}${metric('Current commercial tier',percent(x.profile.rate),x.profile.qualified?'Rate applicable to future commission entries':'Pending first successful client')}${metric('Available for invoicing',money(b.available),b.recovery?'Held pending a clawback settlement':'Unallocated commission, excluding invoice VAT')}${metric('Invoiced — outstanding',money(b.awaiting),'Includes invoices under review')}${metric('Paid this year',money(b.paid),'Actual payments, including invoice tax')}${metric('Outstanding',money(b.outstanding),'Gross unpaid balances, including held commissions')}${metric('Recovery / clawback',money(b.recovery))}</div><div class="two-thirds"><section class="panel"><h2>Your referral link</h2><p class="link-value">https://finsyndeo.com/apply/ref/${h(x.profile.token)}</p><div class="status-line">${pill(x.profile.linkActive?'Active':'Unavailable',x.profile.linkActive)}</div><div class="button-row"><button data-action="copy-link">Copy link</button><button data-action="client-path" ${!x.profile.linkActive?'disabled':''}>Preview client completing it</button><button class="primary" data-action="behalf-path" ${!x.profile.linkActive?'disabled':''}>Complete for a client</button></div><p class="hint">This link attributes referrals. It does not give anyone access to your account.</p></section><section class="panel"><h2>Statement updates</h2>${x.notifications.length?x.notifications.slice(-3).reverse().map(n=>`<p class="mini">${h(n.message)}<br><small>${date(n.created)} · Preview notification</small></p>`).join(''):'<p class="hint">New commission entries will trigger a sign-in reminder. Amounts and client information stay in the portal.</p>'}<button data-view="documents">View my agreement and documents</button></section></div><section class="panel"><h2>How referrals progress</h2><p class="mini">Submitted → Matched → Introduction requested → Introduced → Onboarding → Opened / Activated.</p><p class="hint">SOPHIMA reviews the application before introduction. A successful client counts once, even if several provider relationships open.</p></section>`;}
function loginPage(){return `<div class="signin"><div class="eyebrow">Invitation-only access</div><h1>Introducer sign-in</h1><p class="lead">Use the email address approved by SOPHIMA.</p><section class="panel"><form id="login-form">${field('Email address','email','email','',true)}<button class="primary">Send secure sign-in link</button></form><div id="login-preview" hidden class="notice"></div><p class="hint">Sample invited accounts: alex@introducer.example and bridge@introducer.example.</p></section><p class="privacy-note">Design demonstration only. No sign-in email is sent. A live sign-in service must verify identity, issue short-lived sessions and protect Admin with MFA. A referral token cannot sign you in.</p></div>`;}
function referralsPage(){if(role==='admin')return adminReferralsPage();const x=store.external(ui.intro);return `<h1>My referrals</h1><p class="lead">Provider identities and SOPHIMA’s internal review remain confidential.</p>${table(['Client / application','Service','Provider code','Status','Account activated'],x.applications.flatMap(a=>{const rs=x.relationships.filter(r=>r.application===a.id);return (rs.length?rs:[{}]).map(r=>[`${h(x.clients.find(c=>c.id===a.client)?.name)}<small>${h(a.id)}</small>`,h(r.service||a.service),h(r.provider||'Not selected'),`${pill(r.status||a.status)}${!a.confirmed?'<small>Applicant confirmation pending</small>':''}`,r.activated?'Yes':'No']);}))}<p class="hint">Declined, Closed and Cancelled relationships remain in your history. Closing an account does not remove an achieved tier.</p>`;}
function ledgerPage(){const x=store.external(ui.intro),entries=x.entries.filter(e=>e.currency===ui.currency);return `<div class="section-title"><h1>My commissions</h1><button data-action="export-intro">Export statement CSV</button></div><p class="lead">Each receipt or adjustment has its own entry and permanently stored rate.</p>${table(['Client','Provider','Period','Net provider commission','My rate','My commission','Invoice / payment'],entries.map(e=>{const invoices=x.invoices.filter(i=>i.status!=='Rejected'&&i.allocations.some(a=>a.entry===e.id));return [h(client(e.client)),h(e.provider),`${h(e.period)}<small>${h(e.id)} · ${h(e.kind)}</small>`,money(e.net,e.currency),percent(e.rate),money(e.payable,e.currency),invoices.length?invoices.map(i=>`${h(i.number)} · ${h(store.invoiceStatus(i))}`).join('<br>'):e.payable<0?'Recovery adjustment':'Awaiting invoice'];}))}<div class="button-row"><button class="primary" data-view="invoice">Select commissions and upload invoice</button></div><p class="hint">Receipt tax and your invoice tax are separate. Historical entries retain their original rate.</p>`;}
function invoicePage(){const x=store.external(ui.intro),b=store.balances(ui.intro,ui.currency),entries=x.entries.filter(e=>e.currency===ui.currency&&store.remaining(e)>0);return `<h1>Upload a commission invoice</h1><p class="lead">Combine available entries into one invoice, or invoice part of an entry.</p>${b.recovery?`<div class="notice">A ${money(b.recovery)} clawback needs SOPHIMA settlement. New invoice submission is temporarily held.</div>`:''}<form id="invoice-form" data-draft><section class="panel"><h2>Select available commissions</h2>${table(['Include','Client / provider / period','Available','Amount to invoice'],entries.map(e=>[`<input type="checkbox" name="sel-${h(e.id)}" aria-label="Include ${h(e.id)}">`,`${h(client(e.client))} · ${h(e.provider)}<small>${h(e.period)} · ${h(e.id)}</small>`,money(store.remaining(e)),`<input name="amt-${h(e.id)}" type="number" min="0.01" step="0.01" value="${value(store.remaining(e))}" aria-label="Invoice allocation for ${h(e.id)}">`]))}<p><b>Selected commission subtotal: <output id="invoice-subtotal">${money(0)}</output></b></p></section><section class="panel"><h2>Invoice details</h2><div class="grid">${field('Invoice number','number','text','',true)}${field('Invoice date','date','date',date(store.now()),true)}${select('Invoice VAT / tax treatment','treatment',['No VAT','VAT charged','Reverse charge','Other — Admin review'],'No VAT')}${field('VAT / indirect tax amount','vat','number','0.00',true,'min="0" step="0.01"')}${field('Invoice subtotal excluding VAT','base','number','0.00',true,'min="0" step="0.01"')}${field('Invoice total including VAT','total','number','0.00',true,'min="0" step="0.01"')}</div><label class="field"><span>Upload invoice</span><input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.docx" required></label><p class="hint">Invoice currency: ${h(ui.currency)}. Upload through the portal; emailed invoices do not enter this workflow.</p><div class="button-row"><button type="button" data-action="sample-invoice-file">Download sample invoice file</button><button type="button" data-action="extract-invoice">Preview extraction assistance</button></div><div id="extraction" hidden class="review-preview"></div><button class="primary" ${b.recovery||!entries.length?'disabled':''}>Upload for SOPHIMA review</button></section></form>`;}
function documentsPage(){const x=store.external(ui.intro);return `<h1>My Documents</h1><p class="lead">Your agreements, commercial schedules, invoices and payment confirmations.</p>${table(['Document','Category','Version','Uploaded / signed','Status','Action'],x.documents.map(d=>[h(d.name),h(d.category),h(d.version),date(d.signatureAt||d.date),pill(d.status),`<button data-doc="${h(d.id)}">View / download</button>${d.status==='Awaiting acceptance'?` <button data-accept="${h(d.id)}">Review and accept</button>`:''}`]))}<section id="doc-panel" hidden class="panel"></section><p class="hint">Sample agreement downloads describe the design. They are not signed contracts or a substitute for approved agreement wording.</p>`;}
function invoicesPage(){if(role==='admin')return adminInvoicesPage();const x=store.external(ui.intro);return `<h1>Payments & reconciliation</h1>${table(['Invoice','Subtotal / tax / total','Approved amount','Paid / outstanding','Status','Evidence'],x.invoices.map(i=>[`${h(i.number)} · v${i.revision||1}<small>${h(i.currency)} · ${date(i.date)}</small>`,`${money(i.base,i.currency)} / ${money(i.vat,i.currency)} / ${money(i.total,i.currency)}`,i.status==='Approved'?money(i.total,i.currency):'Pending approval',`${money(store.invoicePaid(i),i.currency)} / ${money(i.status==='Rejected'?0:i.total-store.invoicePaid(i),i.currency)}`,pill(store.invoiceStatus(i),store.invoiceStatus(i)==='Reconciled'),`<button data-doc="${h(i.file)}">Invoice</button>${x.payments.filter(p=>p.invoice===i.id).map(p=>`<p>${date(p.date)} · ${money(p.amount,p.currency)} · ${h(p.status)}<br>${p.proof?`<button data-doc="${h(p.proof)}">Approved payment confirmation</button>`:'Payment recorded; external confirmation pending'}</p>`).join('')}`]))}<section id="doc-panel" hidden class="panel"></section>`;}
function referralPage(){const token=params.get('ref')||intro(ui.intro).token,i=store.s.introducers.find(i=>i.token===token);if(!i||!store.linkActive(i.id))return '<h1>Referral link unavailable</h1><p>Please contact SOPHIMA for assistance.</p>';const behalf=role==='introducer';return `<div class="eyebrow">Referral application · ${h(i.name)}</div><h1>Tell us about the applicant</h1><p class="lead">${behalf?'Complete on behalf of your authorised client.':'Complete your own application.'}</p><p class="hint">This representative sample demonstrates attribution and authority. Production reuses the full existing applicant questionnaires.</p><form id="referral-form" data-draft><section class="panel"><div class="grid">${select('Applicant type','type',['entity','individual','financial_institution'],'entity')}${select('Requested service','service',['Bank account','Merchant account','Both bank and merchant accounts','Financing','Private banking','Correspondent accounts'],'Bank account')}${field('Registered company name / applicant name','name','text','',true)}<label class="field"><span>Country / jurisdiction</span><select name="country">${countryOptions()}</select></label>${field('Company registration number','registration','text','',true)}${field('Applicant contact email','email','email','',true)}</div><label class="field"><span>Brief needs description</span><textarea name="needs" required minlength="20" placeholder="Describe the services the applicant needs."></textarea></label></section><section class="panel"><h2>${behalf?'Client authority':'Applicant confirmation'}</h2>${behalf?check(h(M.AUTHORITY),'authority'):check('I accept the Applicant Terms (sample acknowledgement).','terms')+check('I acknowledge the Privacy Notice (sample acknowledgement).','privacy')}<p class="hint">${behalf?'SOPHIMA will request direct applicant confirmation before introducing a provider.':'Production will verify your applicant sign-in separately from this referral link.'}</p><button class="primary">Submit sample application</button></section></form><div id="submitted-preview"></div>`;}
function confirmPage(){const a=store.s.applications.find(a=>a.id===ui.confirmApp);if(!a)return '<h1>Select an application first</h1>';const c=store.s.clients.find(c=>c.id===a.client);return `<h1>Confirm your application</h1><p class="lead">${h(c.name)} · ${h(a.service)} · ${h(a.id)}</p><p class="notice">Review demonstration: sign in as the applicant using their recorded email. Live authentication is not connected.</p><section class="panel"><h2>Information submitted on your behalf</h2><dl class="compact-dl"><dt>Applicant</dt><dd>${h(c.name)}</dd><dt>Country / jurisdiction</dt><dd>${h(c.country)}</dd><dt>Registration</dt><dd>${h(c.registration||'Not applicable')}</dd><dt>Requested service</dt><dd>${h(a.service)}</dd><dt>Contact email</dt><dd>${h(c.email)}</dd><dt>Needs description</dt><dd>${h(a.needs||'Full assessment details would be displayed from the existing questionnaire.')}</dd></dl><p class="hint">Contact SOPHIMA if corrections are needed before you confirm. Production will reuse the existing editable assessment summary.</p></section><p class="notice">Applicant identity simulation only. Production must verify sign-in before this screen; Admin cannot accept on behalf of the applicant.</p><form id="confirm-form"><section class="panel">${field('Applicant email','email','email',c.email,true)}${check('Simulate verification of my own applicant email for this review only.','verifyDemo')}${check('I have reviewed and confirm the information submitted on my behalf.','reviewed')}${check('I accept the Applicant Terms (sample).','terms')}${check('I acknowledge the Privacy Notice (sample).','privacy')}<button class="primary">Confirm application</button></section></form>`;}
function overviewPage(){const a=intro('I-A'),b=intro('I-B');return `<div class="eyebrow">SOPHIMA administration</div><h1>Introducer relationships & accounting</h1><p class="lead">Manage approved introducers, provider participation and commission payables.</p><div class="metrics">${metric('Approved introducers',store.s.introducers.filter(i=>i.status==='Active').length)}${metric('Referred clients',store.s.clients.filter(c=>c.introducer).length)}${metric('Active provider relationships',store.s.relationships.filter(r=>r.status==='Opened / Activated').length)}${metric('Accounting exceptions',store.s.draftReports.length+store.s.payments.filter(p=>p.status==='Mismatch').length)}</div><div class="two-thirds"><section class="panel"><h2>Test the automatic tiers</h2><p class="mini"><b>Alex Morgan: ${percent(store.rate('I-A'))}</b> · ${store.qualified('I-A')} distinct successful client(s).</p><p class="hint">Cedar Trading already has two activated relationships. It counts once.</p><div class="button-row"><button data-activate="R3" ${store.s.clients.find(c=>c.id==='C2').qualifiedAt?'disabled':''}>Activate Client 2 → 40%</button><button data-activate="R4" ${!store.s.clients.find(c=>c.id==='C2').qualifiedAt||store.s.clients.find(c=>c.id==='C3').qualifiedAt?'disabled':''}>Activate Client 3 → 50%</button></div><button data-action="future-receipt">Post future Cedar commission at ${percent(store.rate('I-A'))}</button><p class="hint">Creates a sample EUR 1,000 net receipt. Historic July and August entries retain 30%.</p></section><section class="panel"><h2>Test bespoke terms</h2><p>Bridge Advisory Ltd</p><dl class="compact-dl"><dt>Achieved automatic tier</dt><dd>${percent(b.achieved)}</dd><dt>Effective commercial rate</dt><dd>${percent(store.rate('I-B'))}</dd><dt>Commission mode</dt><dd>${h(store.mode('I-B'))}</dd></dl><div class="button-row"><button data-profile="I-B">Review override controls</button><button data-perspective="I-B">See introducer’s view</button></div><p class="hint">The introducer sees the effective rate, never the override controls or internal reason.</p></section></div><section class="panel"><h2>Accounting review queue</h2>${table(['Record','Reason','Action'],[...store.s.draftReports.map(d=>[h(d.id),h(d.reason),'<button data-view="commissions">Review provider receipt</button>']),...store.s.invoices.filter(i=>i.status==='Under Review').map(i=>[h(i.number),'Invoice awaiting approval','<button data-view="invoices">Review invoice</button>']),...store.s.payments.filter(p=>p.status==='Mismatch').map(p=>[h(p.reference),'Bank evidence does not match recorded payment','<button data-view="invoices">Resolve reconciliation</button>'])])}</section>`;}
function introPicker(){return `<label class="field"><span>Introducer profile</span><select id="admin-intro">${store.s.introducers.map(i=>`<option value="${h(i.id)}" ${i.id===ui.adminIntro?'selected':''}>${h(i.name)} · ${h(i.type)}</option>`).join('')}</select></label>`;}
function profilePage(){const i=intro(ui.adminIntro),b=store.balances(i.id,'EUR'),rel=store.s.relationships.filter(r=>store.s.clients.find(c=>c.id===r.client)?.introducer===i.id),ev=i.rateEvents.at(-1),ds=store.s.documents.filter(d=>d.owner===i.id);return `<h1>Introducer profiles</h1>${introPicker()}<div class="two-thirds"><section class="panel"><h2>${h(i.name)}</h2><dl class="compact-dl"><dt>Type</dt><dd>${h(i.type)}</dd><dt>Country / tax residence</dt><dd>${h(i.country)} / ${h(i.taxResidency)}</dd><dt>Email</dt><dd>${h(i.email)}</dd><dt>VAT registered</dt><dd>${i.vatRegistered?'Yes · '+h(i.vatNumber):'No'}</dd><dt>Tax notes</dt><dd>${h(i.taxNotes)}</dd><dt>Created</dt><dd>${date(i.created)}</dd><dt>Referral token</dt><dd>${h(i.token)} · ${store.linkActive(i.id)?'Active':'Inactive'}</dd></dl><form id="access-form"><div class="grid">${select('Introducer status','status',['Invited','Active','Suspended','Terminated'],i.status)}</div>${check('Suspend referral link only','linkSuspended',i.linkSuspended)}<div class="button-row"><button>Save access settings</button></div></form><p class="hint">Suspension stops new referrals, not historical entitlement. Admin can still settle existing obligations.</p></section><section class="panel"><h2>Portfolio statistics</h2><dl class="compact-dl"><dt>Referred clients</dt><dd>${store.s.clients.filter(c=>c.introducer===i.id).length}</dd><dt>Successful unique clients</dt><dd>${store.qualified(i.id)}</dd><dt>Active relationships</dt><dd>${rel.filter(r=>r.status==='Opened / Activated').length}</dd><dt>Provider net commissions</dt><dd>${money(store.s.entries.filter(e=>e.introducer===i.id&&e.currency==='EUR').reduce((n,e)=>n+e.net,0),'EUR')}</dd><dt>Introducer commissions</dt><dd>${money(store.s.entries.filter(e=>e.introducer===i.id&&e.currency==='EUR').reduce((n,e)=>n+e.payable,0),'EUR')}</dd><dt>Paid this year</dt><dd>${money(b.paid,'EUR')}</dd><dt>Outstanding</dt><dd>${money(b.outstanding,'EUR')}</dd></dl><p class="hint">Statistics above are EUR only; Accounting reports separate all currencies.</p></section></div><section class="panel"><h2>Commission terms · Admin only</h2><p class="mini">Achieved tier: <b>${percent(i.achieved)}</b> · Applicable now: <b>${percent(store.rate(i.id))}</b>. Successful clients are never automatically removed.</p><form id="rate-form" data-draft><div class="grid">${select('Commission mode','mode',['Automatic Tiering','Manual Override'],store.mode(i.id)==='manual'?'Manual Override':'Automatic Tiering')}${field('Custom rate (%)','rate','number',value(ev?.rate||i.achieved),true,'min="0" max="100" step="0.01"')}${field('Effective date and time (UTC)','effective','datetime-local',store.now().slice(0,19),true,'step="1"')}<label class="field"><span>Signed / accepted contractual record</span><select name="document">${ds.filter(d=>d.status==='Accepted'&&['Agreement','Schedule','Addendum'].includes(d.category)).map(d=>`<option value="${h(d.id)}">${h(d.name)} · ${h(d.version)}</option>`).join('')}</select></label></div>${field('Internal reason (optional, never visible to introducer)','reason','text',ev?.reason||'')}${check('The accepted commercial terms authorise this change.','confirm')}<div class="button-row"><button class="primary">Save prospective rate change</button></div><p class="hint">Switching off Manual Override resumes the achieved automatic tier. Historical ledger rates remain unchanged. Future-dated terms take effect at their recorded UTC time.</p></form><details><summary>Commercial terms history</summary>${table(['Effective (UTC)','Mode','Rate','Author / record','Internal reason'],i.rateEvents.map(e=>[h(e.effective),h(e.mode),percent(e.rate),`${h(e.actor)}<small>${h(e.document)}</small>`,h(e.reason)]))}</details></section><section class="panel"><h2>Agreement and documents</h2><p class="hint">Current agreement record: ${h(i.agreementVersion)}. Initial effective date: ${date(ds.find(d=>d.category==='Agreement'&&d.status==='Accepted')?.effective||ds.find(d=>d.category==='Agreement'&&d.status==='Accepted')?.date)}. New versions are retained with their acceptance time.</p>${table(['Document / version','Status','Date','Action'],ds.map(d=>[`${h(d.name)}<small>${h(d.version)}</small>`,pill(d.status),date(d.signatureAt||d.date),`<button data-doc="${h(d.id)}">View / download</button>`]))}<form id="agreement-form" data-draft><label class="field"><span>Load complete review draft</span><select name="template"><option value="Agreement">Master Introducer Agreement</option><option value="Schedule">Standard Schedule 1 — 30%, 40%, 50%</option><option value="Bespoke">Bespoke Schedule 1</option><option value="Addendum">Addendum implementation checklist</option></select></label><div class="grid">${select('Publish agreement document','category',['Agreement','Schedule','Addendum'],'Agreement')}${field('Version','version','text','',true)}</div><label class="field"><span>Full review draft text — complete all placeholders before real execution</span><textarea name="body" required placeholder="Select a template to review the complete clauses. This is not an executed agreement."></textarea></label><button>Publish for introducer acceptance</button></form><details><summary>Make another document available to this introducer</summary><form id="admin-document-form"><label class="field"><span>Upload document</span><input name="file" type="file" accept=".pdf,.txt,.docx,.png,.jpg,.jpeg" required></label>${check('This copy is appropriate to share with this introducer.','safeToShare')}<button>Store internal original for disclosure review</button><p class="hint">Use introducer-safe copies. Provider agreements and internal due diligence reports stay in SOPHIMA’s restricted file.</p></form></details></section><section id="doc-panel" class="panel" hidden></section><details class="panel"><summary>Create an invited introducer</summary><form id="create-intro" data-draft><div class="grid">${field('Name / registered company name','name','text','',true)}${select('Individual or company','type',['Individual','Company'],'Individual')}${field('Email','email','email','',true)}<label class="field"><span>Country</span><select name="country">${countryOptions()}</select></label><label class="field"><span>Tax residence</span><select name="taxResidency">${countryOptions()}</select></label>${field('VAT number (if registered)','vatNumber')}</div>${check('VAT registered','vatRegistered')}${field('Tax notes (optional)','taxNotes')}<button class="primary">Create invitation-only account</button><p class="hint">The unique referral link stays inactive until accepted Agreement, accepted Schedule 1 and Admin activation are all present.</p></form></details><details class="panel"><summary>Review future-dated changes</summary><form id="clock-form">${field('Sample clock (UTC)','clock','datetime-local',store.now().slice(0,19),true,'step="1"')}<button>Advance review clock</button><p class="hint">Review tool only. Production uses a trusted server clock.</p></form></details>`;}
function providersPage(){const p=provider(ui.provider);return `<h1>Provider access for introduced cases</h1><p class="lead">Add referral participation rules to each existing provider profile.</p><label class="field"><span>Provider · actual names visible to Admin only</span><select id="admin-provider">${store.s.providers.map(x=>`<option value="${h(x.id)}" ${x.id===p.id?'selected':''}>${h(x.id)} · ${h(x.name)}</option>`).join('')}</select></label><section class="panel"><h2>${h(p.id)} · ${h(p.name)}</h2><form id="provider-form" data-draft><div class="grid">${select('Eligible for introducer referrals','eligible',['Yes','No'],p.eligible?'Yes':'No')}${select('Client-level commission reporting available','reporting',['Yes','No'],p.reporting?'Yes':'No')}${select('Reporting frequency','frequency',['Monthly','Quarterly','Annually','Ad Hoc','Other'],p.frequency)}${select('Receipt VAT / tax default','taxDefault',['included','added','none','reverse','withholding','manual'],p.taxDefault)}${select('Commission currency default','currency',['EUR','GBP','USD','CHF'],p.currency)}</div>${field('Internal provider notes','notes','text',p.notes)}<p class="mini"><b>Introducer visibility:</b> provider code only. Actual identity and internal provider documents are excluded.</p><details><summary>Introducer-specific participation</summary>${store.s.introducers.map(i=>select(h(i.name),'override-'+i.id,['Inherit global setting','Exclude','Allow'],p.overrides[i.id]==='exclude'?'Exclude':p.overrides[i.id]==='allow'?'Allow':'Inherit global setting')).join('')}<p class="hint">Allow can override the global participation switch. It cannot bypass client-level reporting, approved products, agreement, legal or due diligence gates.</p></details><button class="primary">Save provider settings</button></form></section>${table(['Provider','Global eligibility','Client reporting','Reporting','A participates','B participates'],store.s.providers.map(p=>[`${h(p.id)}<small>${h(p.name)}</small>`,p.eligible?'Yes':'No',p.reporting?'Yes':'No',h(p.frequency),store.eligible(p.id,'I-A')?'Yes':'No',store.eligible(p.id,'I-B')?'Yes':'No']))}<p class="hint">This sample implements the additional introducer gate. It does not replace the full existing applicant/product matching rules.</p>`;}
function adminReferralsPage(){return `<h1>Clients, applications & relationships</h1><p class="lead">The client ID anchors attribution and successful-client tiering. Provider relationships remain separate.</p>${table(['Client / application','Introducer','Service','Confirmation / review','Action'],store.s.applications.map(a=>[`${h(client(a.client))}<small>${h(a.client)} · ${h(a.id)}</small>`,a.introducer?h(intro(a.introducer).name):'Direct',h(a.service),`${a.confirmed?'Applicant confirmed':'Applicant confirmation required'}<small>${a.ddClear?'SOPHIMA DD gate cleared (sample)':'Due diligence pending'}</small>`,!a.confirmed?`<button data-confirm="${h(a.id)}">Preview applicant confirmation</button>`:'—']))}<section class="panel"><h2>Provider relationship status</h2>${table(['Client / relationship','Provider — Admin only','Service','External status','Action'],store.s.relationships.map(r=>[`${h(client(r.client))}<small>${h(r.id)} · ${h(r.application)}</small>`,`${h(r.provider)}<small>${h(provider(r.provider).name)}</small>`,h(r.service),`<select data-status="${h(r.id)}" aria-label="Status for ${h(r.id)}">${options(M.STATUSES,r.status)}</select>`,`<button data-save-status="${h(r.id)}">Save status</button>`]))}<p class="hint">A status cannot pass introduction until applicant confirmation, the SOPHIMA DD gate and current referral eligibility are all satisfied. Closed relationships retain qualification and history.</p></section><details class="panel"><summary>Select a provider relationship for an application</summary><form id="relationship-form"><div class="grid"><label class="field"><span>Application</span><select name="application">${store.s.applications.map(a=>`<option value="${h(a.id)}">${h(client(a.client))} · ${h(a.id)}</option>`).join('')}</select></label><label class="field"><span>Provider</span><select name="provider">${store.s.providers.map(p=>`<option value="${h(p.id)}">${h(p.id)} · ${h(p.name)}</option>`).join('')}</select></label>${select('Service','service',['Bank account','Merchant account','Financing','Private banking','Correspondent accounts'],'Bank account')}</div><button>Add matching relationship</button></form></details><details class="panel"><summary>Review introduction clearance</summary><form id="clearance-form"><label class="field"><span>Application</span><select name="application">${store.s.applications.map(a=>`<option value="${h(a.id)}">${h(client(a.client))} · ${h(a.id)}</option>`).join('')}</select></label>${check('The internal due diligence report and required identity checks are reviewed and cleared.','clearance')}<button>Record sample DD clearance</button><p class="hint">This demonstrates the gate only. It never performs or certifies screening.</p></form></details>`;}
const TAXES={included:'VAT included in gross',added:'VAT added separately',none:'No VAT',reverse:'Reverse charge',withholding:'Withholding tax (no cash VAT)',manual:'Other / manual treatment'};
function commissionsPage(){const p=provider(ui.provider),rs=store.s.relationships.filter(r=>r.provider===p.id&&r.activated);return `<div class="section-title"><h1>Add provider commissions</h1><button data-view="reports">Open reconciliation report</button></div><label class="field"><span>Provider</span><select id="admin-provider">${store.s.providers.map(p=>`<option value="${h(p.id)}" ${p.id===ui.provider?'selected':''}>${h(p.id)} · ${h(p.name)}</option>`).join('')}</select></label><p class="lead">Enter actual cash receipts from the provider report. Save several clients together.</p><form id="commission-form" data-draft><section class="panel"><h2>Provider receipt header</h2><p class="hint">For one remittance covering several clients, enter the same reference on each line and the verified total here. Line cash allocations must reconcile exactly.</p>${field('Provider statement reference','statementReference','text','',true)}${field('Verified bank receipt total (single remittance batch)','receiptTotal','number','',true,'min="0" step="0.01"')}</section>${rs.map((r,n)=>{const c=store.s.clients.find(c=>c.id===r.client),rate=c.introducer?store.rate(c.introducer):0;return `<section class="receipt-card" data-receipt="${h(r.id)}"><h3>${check(h(c.name)+' · '+h(r.id)+' · '+h(r.service),'include-'+r.id)}</h3><p class="mini">${c.introducer?'Introducer: '+h(intro(c.introducer).name)+' · '+percent(rate):'Direct client · no introducer share'}</p><div class="grid">${field('Commission period','period-'+r.id,'text','October 2026',true)}${field('Receipt date','date-'+r.id,'date',date(store.now()),true)}${select('Currency','currency-'+r.id,['EUR','GBP','USD','CHF'],p.currency)}${field('Gross provider commission','gross-'+r.id,'number','0.00',true,'min="0" step="0.01"')}${select('VAT / tax treatment','tax-'+r.id,Object.keys(TAXES),p.taxDefault)}${field('VAT / indirect tax amount','vat-'+r.id,'number','0.00',true,'min="0" step="0.01"')}</div><details><summary>Deductions and receipt reference</summary><div class="grid">${field('Withholding tax','withholding-'+r.id,'number','0.00',true,'min="0" step="0.01"')}${field('Direct bank / intermediary charges','charges-'+r.id,'number','0.00',true,'min="0" step="0.01"')}${field('Cash actually received (including any cash VAT)','received-'+r.id,'number','0.00',true,'min="0" step="0.01"')}${field('Bank receipt reference — may be shared across client lines','reference-'+r.id,'text','',false)}</div>${check('I confirm these component amounts were actually received.','received-confirm-'+r.id)}</details><p class="mini"><b>Net commission: <output data-net="${h(r.id)}">—</output> · Introducer share: <output data-share="${h(r.id)}">—</output></b></p><div data-tax-note="${h(r.id)}" class="hint"></div></section>`;}).join('')}<div class="button-row"><button class="primary" ${!rs.length?'disabled':''}>Save selected receipts</button></div><p class="hint">Tax fields reflect the provider’s receipt. Introducer invoice tax is reviewed separately. For partial provider payments, enter only the actual paid portion with a distinct receipt reference. Rates are fixed when each final ledger entry is posted.</p></form><section class="panel"><h2>Manual review queue</h2>${store.s.draftReports.map(d=>`<form data-review-report="${h(d.id)}"><div class="notice"><b>${h(d.id)} · ${h(d.period)}</b><br>${h(d.reason)}<br>Actual received: ${money(d.received,d.currency)}. No payable entry exists yet.</div><div class="grid">${field('Approved net commission excluding tax','net','number',value(d.received-d.vat),true,'min="0" step="0.01"')}${field('Accounting decision / authorised adjustment reason','reason','text','',true)}</div><button>Approve treatment and post ledger entry</button></form>`).join('')||'<p class="hint">No held reports.</p>'}</section><details class="panel"><summary>Refund / reversal / clawback</summary><form id="adjustment-form"><label class="field"><span>Original receipt</span><select name="entry">${store.s.entries.filter(e=>e.kind==='Receipt').map(e=>`<option value="${h(e.id)}">${h(e.id)} · ${h(client(e.client))} · ${h(e.provider)} · ${money(e.net,e.currency)} · ${percent(e.rate)}</option>`).join('')}</select></label><div class="grid">${field('Net reversal amount','amount','number','',true,'min="0.01" step="0.01"')}${field('Adjustment / credit reference','reference','text','',true)}</div>${field('Reason','note','text','',true)}<button>Post separate reversal entry</button><p class="hint">The original rate and currency are used. Prior invoices and payments are unchanged; a recovery balance may be created.</p></form></details>`;}
function adminInvoicesPage(){const invoices=store.s.invoices;const selected=invoices.find(i=>i.id===ui.invoiceId)||invoices.at(-1);let detail='';if(selected){const i=selected,paid=store.invoicePaid(i),ps=store.s.payments.filter(p=>p.invoice===i.id);detail=`<section class="panel"><h2>${h(i.number)} · v${i.revision||1} · ${h(intro(i.introducer).name)}</h2><p class="mini">Commission subtotal ${money(i.base,i.currency)} + invoice tax ${money(i.vat,i.currency)} = total ${money(i.total,i.currency)}. ${pill(store.invoiceStatus(i))}</p><p>${h(i.treatment)}</p><button data-doc="${h(i.file)}">Review uploaded invoice</button>${table(['Ledger entry','Client / provider','Period','Allocated amount'],i.allocations.map(a=>{const e=store.s.entries.find(e=>e.id===a.entry);return [h(e.id),`${h(client(e.client))} · ${h(e.provider)}`,h(e.period),money(a.amount,i.currency)];}))}${i.status==='Under Review'?`<form id="invoice-review">${field('Review note / reason for rejection','note')}<div class="button-row"><button class="primary" name="decision" value="approve">Approve invoice and tax treatment</button><button name="decision" value="reject">Reject and release allocations</button></div></form>`:`<p class="hint">Reviewed by ${h(i.reviewer||'—')}: ${h(i.note||'No additional note')}</p>`}${i.status==='Approved'&&i.total>paid&&!ps.some(p=>p.status==='Mismatch')?`<details open><summary>Record payment — outstanding ${money(i.total-paid,i.currency)}</summary><form id="payment-form" data-draft><div class="grid">${field('Payment amount','amount','number',value(i.total-paid),true,'min="0.01" step="0.01"')}${field('Payment date','date','date',date(store.now()),true)}${select('Payment currency','currency',['EUR','GBP','USD','CHF'],i.currency)}${field('Bank payment reference','reference','text','',true)}</div><label class="field"><span>Upload payment evidence</span><input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt" required></label><button class="primary">Record payment</button><p class="hint">Recording a payment reduces invoice outstanding. Bank reconciliation is a separate check; discrepancies reopen the outstanding balance.</p></form></details>`:''}<h3>Payment history</h3>${ps.map(p=>`<div class="receipt-card"><p>${money(p.amount,p.currency)} · ${date(p.date)} · ${h(p.reference)} · ${pill(p.status,p.status==='Reconciled')}</p><button data-doc="${h(p.proof)}">View proof</button>${!['Reconciled','Superseded'].includes(p.status)?`<form data-reconcile="${h(p.id)}"><div class="grid">${field('Amount confirmed in bank evidence','actual','number',value(p.actual??p.amount),true,'min="0" step="0.01"')}${field('Reference confirmed in bank evidence','reference','text',p.bankReference||p.reference,true)}</div>${field('Reconciliation note (optional)','note','text',p.note||'')}<button>Compare and reconcile</button></form>${p.status==='Mismatch'?`<form data-correct-payment="${h(p.id)}">${field('Evidence review / correction reason','reason','text','',true)}<button>Accept evidenced amount as a separate correction</button></form>`:''}`:p.status==='Superseded'?'<p class="hint">Original payment retained. Its separate evidenced correction is used in the totals.</p>':'<p class="hint">Amount, currency and reference reconciled. No ledger entry has been recalculated.</p>'}</div>`).join('')||'<p class="hint">No payments recorded.</p>'}</section>`;}
return `<h1>Invoice approval, payment & reconciliation</h1>${table(['Invoice / introducer','Currency','Approved / invoice total','Paid','Outstanding','Status','Action'],invoices.map(i=>[`${h(i.number)}<small>${h(intro(i.introducer).name)}</small>`,h(i.currency),money(i.total,i.currency),money(store.invoicePaid(i),i.currency),i.status==='Rejected'?money(0,i.currency):money(i.total-store.invoicePaid(i),i.currency),pill(store.invoiceStatus(i)),`<button data-invoice="${h(i.id)}">Review</button>`]))}${detail}<section id="doc-panel" class="panel" hidden></section><details class="panel"><summary>Resolve clawback / recovery balances</summary><form id="recovery-form">${introPicker()}${select('Currency','currency',['EUR','GBP','USD','CHF'],'EUR')}${field('Agreed credit / offset reference and reason','note','text','',true)}<button>Offset against available unbilled commission</button><p class="hint">No settled invoice is altered. Only unbilled commission is offset against the recovery balance, under an authorised agreement.</p></form><form id="refund-form"><div class="grid">${field('Confirmed introducer refund amount','amount','number','',true,'min="0.01" step="0.01"')}${field('Reconciled bank refund reference','reference','text','',true)}</div><p class="hint">Uses the introducer and currency selected above.</p><button>Record confirmed recovery refund</button></form></details>`;}
function reportData(){const kind=ui.reportKind||'Incoming provider commissions',f=ui.reportFilters||{},match=e=>(!f.provider||e.provider===f.provider)&&(!f.client||e.client===f.client)&&(!f.introducer||e.introducer===f.introducer)&&(!f.period||e.period===f.period)&&(!f.currency||e.currency===f.currency);if(kind==='Provider reconciliation'){const rs=store.s.relationships.filter(r=>!f.provider||r.provider===f.provider);return {heads:['Provider code','Actual provider (Admin only)','Client','Origin','Relationship','Status','Activated','Start date','Reporting status','Latest period'],rows:rs.map(r=>{const c=store.s.clients.find(c=>c.id===r.client),e=store.s.entries.filter(e=>e.relationship===r.id&&e.kind==='Receipt').at(-1);return [r.provider,provider(r.provider).name,c.name,c.introducer?intro(c.introducer).name:'Direct',r.id,r.status,r.activated?'Yes':'No',date(r.start),r.reportingStatus,e?.period||'Not recorded'];})};}if(kind==='Invoices'){return {heads:['Invoice','Introducer','Currency','Commission subtotal','Invoice VAT','Invoice total','Paid','Outstanding','Status'],rows:store.s.invoices.filter(i=>(!f.introducer||i.introducer===f.introducer)&&(!f.currency||i.currency===f.currency)).map(i=>[i.number,intro(i.introducer).name,i.currency,value(i.base),value(i.vat),value(i.total),value(store.invoicePaid(i)),value(i.status==='Rejected'?0:i.total-store.invoicePaid(i)),store.invoiceStatus(i)])};}if(kind==='Payments'){return {heads:['Invoice','Introducer','Date','Currency','Payment amount','Confirmed bank amount','Reference','Status'],rows:store.s.payments.filter(p=>{const i=store.s.invoices.find(i=>i.id===p.invoice);return (!f.introducer||i.introducer===f.introducer)&&(!f.currency||p.currency===f.currency);}).map(p=>{const i=store.s.invoices.find(i=>i.id===p.invoice);return [i.number,intro(i.introducer).name,p.date,p.currency,value(p.amount),p.actual===undefined?'Unconfirmed':value(p.actual),p.reference,p.status];})};}
const es=store.s.entries.filter(match);if(kind==='Introducer payables'){return {heads:['Entry','Introducer','Client','Provider','Period','Currency','Rate (%)','Commission','Invoice allocation / offsets','Available (before recovery hold)'],rows:es.filter(e=>e.introducer).map(e=>[e.id,intro(e.introducer).name,client(e.client),e.provider,e.period,e.currency,e.rate/100,value(e.payable),value(store.allocated(e.id)),value(store.remaining(e))])};}return {heads:['Entry','Provider','Actual provider (Admin only)','Client','Direct / introduced','Period','Receipt date','Currency','Gross','VAT','Withholding','Charges','Cash received','Net','Introducer rate (%)','Introducer commission','Type'],rows:es.map(e=>[e.id,e.provider,provider(e.provider).name,client(e.client),e.introducer?intro(e.introducer).name:'Direct',e.period,e.date,e.currency,value(e.gross),value(e.vat),value(e.withholding||0),value(e.charges||0),value(e.received),value(e.net),e.rate/100,value(e.payable),e.kind])};}
function reportsPage(){const f=ui.reportFilters||{},kind=ui.reportKind||'Incoming provider commissions',invoiceKind=['Invoices','Payments'].includes(kind),data=reportData(),groups={};store.s.entries.filter(e=>(!f.provider||e.provider===f.provider)&&(!f.client||e.client===f.client)&&(!f.introducer||e.introducer===f.introducer)&&(!f.period||e.period===f.period)&&(!f.currency||e.currency===f.currency)).forEach(e=>{groups[e.currency]||={net:0,payable:0,cash:0};groups[e.currency].net+=e.net;groups[e.currency].cash+=e.received;groups[e.currency].payable+=e.payable;});return `<div class="section-title"><h1>Accounting reports</h1><button data-action="export-report">Export displayed report CSV</button></div><p class="lead">Filter receipts and payables by provider, client, introducer, period and currency. Reconcile all clients for a provider.</p><section class="panel"><div class="grid">${select('Report','reportKind',['Incoming provider commissions','Introducer payables','Provider reconciliation','Invoices','Payments'],kind)}<label class="field"><span>Currency</span><select data-filter="currency"><option value="">All — separate totals</option>${options(['EUR','GBP','USD','CHF'],f.currency)}</select></label>${!invoiceKind?`<label class="field"><span>Provider</span><select data-filter="provider"><option value="">All providers</option>${store.s.providers.map(p=>`<option value="${p.id}" ${f.provider===p.id?'selected':''}>${h(p.id)} · ${h(p.name)}</option>`).join('')}</select></label>`:''}${!invoiceKind&&kind!=='Provider reconciliation'?`<label class="field"><span>Client</span><select data-filter="client"><option value="">All clients</option>${store.s.clients.map(c=>`<option value="${c.id}" ${f.client===c.id?'selected':''}>${h(c.name)}</option>`).join('')}</select></label><label class="field"><span>Commission period</span><select data-filter="period"><option value="">All periods</option>${options([...new Set(store.s.entries.map(e=>e.period))],f.period)}</select></label>`:''}${kind!=='Provider reconciliation'?`<label class="field"><span>Introducer</span><select data-filter="introducer"><option value="">All origins</option>${store.s.introducers.map(i=>`<option value="${i.id}" ${f.introducer===i.id?'selected':''}>${h(i.name)}</option>`).join('')}</select></label>`:''}</div></section>${!invoiceKind&&kind!=='Provider reconciliation'?Object.entries(groups).map(([c,v])=>`<div class="metrics">${metric(c+' cash received',money(v.cash,c))}${metric(c+' net commissions',money(v.net,c))}${metric(c+' introducer commissions',money(v.payable,c))}</div>`).join(''):''}${table(data.heads,data.rows.map(row=>row.map(h)))}<p class="hint">${invoiceKind?'Invoice and payment totals use invoice-level currency and introducer filters. They are not silently apportioned to provider periods.':'Currency totals are never converted or combined. Provider reconciliation includes direct and introduced clients, including closed relationships.'}</p>`;}
function auditPage(){return `<div class="section-title"><h1>Audit trail</h1><button data-action="export-audit">Export audit CSV</button></div><p class="lead">Material changes record the actor, previous value, new value, time and record.</p>${table(['Time (UTC)','Actor','Record','Event','Previous','New'],store.s.audit.slice().reverse().map(a=>[h(a.at),h(a.actor),h(a.record),h(a.event),`<div class="audit-value">${h(JSON.stringify(a.before,null,2))}</div>`,`<div class="audit-value">${h(JSON.stringify(a.after,null,2))}</div>`]))}<p class="hint">Local prototype history is editable by someone with browser access. Production requires an append-only server audit log, protected access and retention controls.</p>`;}
function receiptValues(id){const f=$('#commission-form'),get=n=>f.elements[n+'-'+id];return {relationship:id,period:get('period').value,date:get('date').value,currency:get('currency').value,gross:M.cents(get('gross').value),vat:M.cents(get('vat').value),treatment:get('tax').value,withholding:M.cents(get('withholding').value),charges:M.cents(get('charges').value),received:M.cents(get('received').value),sourceRef:get('reference').value,confirmReceived:get('received-confirm').checked};}
function refreshCalculations(){if($('#commission-form'))$$('[data-receipt]').forEach(card=>{const id=card.dataset.receipt;try{const v=receiptValues(id),c=store.calculation(v),r=store.s.relationships.find(r=>r.id===id),cl=store.s.clients.find(c=>c.id===r.client),rate=cl.introducer?store.rate(cl.introducer):0;card.querySelector('[data-net]').textContent=money(c.net,v.currency);card.querySelector('[data-share]').textContent=money(M.share(c.net,rate),v.currency);card.querySelector('[data-tax-note]').textContent=TAXES[v.treatment]+'. '+(v.treatment==='added'?'Gross excludes VAT; add the separate VAT amount.':'Gross includes any cash VAT.')+(c.hold?' Requires accounting review before a payable can be posted.':' Cash amounts agree.');}catch(e){card.querySelector('[data-net]').textContent='Check amounts';card.querySelector('[data-tax-note]').textContent=e.message;}});if($('#invoice-form')){const f=$('#invoice-form');let n=0;store.s.entries.filter(e=>e.introducer===ui.intro&&e.currency===ui.currency).forEach(e=>{if(f.elements['sel-'+e.id]?.checked){try{n+=M.cents(f.elements['amt-'+e.id].value);}catch{}}});$('#invoice-subtotal').textContent=money(n);}}
function formHandler(id,fn){const f=$('#'+id);if(f)f.onsubmit=async ev=>{ev.preventDefault();try{await fn(f,ev);}catch(e){notify(e.message,true);} };}
