$$('[data-doc]').forEach(b=>b.onclick=()=>{let d;try{d=store.documentView(b.dataset.doc);}catch(e){notify(e.message,true);return;}const p=$('#doc-panel');if(p){p.hidden=false;p.innerHTML=`<h2>${h(d.name)}</h2>${d.dataURL?'<p>Uploaded sample file. Use the download button to open it.</p>':`<pre class="review-preview doc-view">${h(d.body)}</pre>`}<button id="download-selected-doc">Download document</button>`;$('#download-selected-doc').onclick=()=>downloadDoc(d.id);p.scrollIntoView({behavior:'smooth',block:'start'});}else downloadDoc(d.id);});
$$('[data-accept]').forEach(b=>b.onclick=()=>{const d=store.s.documents.find(d=>d.id===b.dataset.accept),p=$('#doc-panel');p.hidden=false;p.innerHTML=`<h2>${h(d.name)} · ${h(d.version)}</h2><pre class="review-preview doc-view">${h(d.body)}</pre><form id="accept-form">${check('I have reviewed and accept this sample version.','accepted')}<button class="primary">Record sample acceptance</button></form><p class="hint">Production needs legally approved acceptance and signature evidence. This action is not a real signature.</p>`;formHandler('accept-form',f=>run(()=>store.acceptDoc(d.id,f.elements.accepted.checked),'Document acceptance recorded in the sample.'));});
formHandler('login-form',f=>{const email=f.elements.email.value.trim().toLowerCase(),i=store.s.introducers.find(i=>i.email===email&&i.status!=='Terminated');if(!i)throw Error('No sample invitation was found. Introducers do not register publicly.');$('#login-preview').hidden=false;$('#login-preview').innerHTML='Preview: no email has been sent. A live secure link would verify this invited email.<div class="button-row"><button id="continue-invited">Continue to invited account preview</button></div>';$('#continue-invited').onclick=()=>perspective(i.id);});
formHandler('referral-form',f=>{const v=data(f);if(v.type==='individual')v.registration='';if(!v.needs||v.needs.trim().length<20)throw Error('Please provide a brief useful description of the applicant’s needs.');if(role==='applicant'){store.loginApplicantDemo(v.email);}const id=store.submitReferral(params.get('ref')||intro(ui.intro).token,{...v,onBehalf:role==='introducer'});save();capture();render();$('#submitted-preview').innerHTML=`<section class="panel"><h2>Sample application submitted</h2><p>${h(id)} is attributed to ${h(store.s.applications.find(a=>a.id===id).introducer)}. ${role==='introducer'?'Applicant confirmation is required before introduction.':'SOPHIMA review is required before introduction.'}</p><button data-go-admin>Review in SOPHIMA Admin</button></section>`;$('[data-go-admin]').onclick=()=>{perspective('admin');view('referrals');};notify('Application saved with immutable referral attribution.');});
const t=$('#referral-form [name=type]');if(t){const update=()=>{const service=$('#referral-form [name=service]'),choices=t.value==='individual'?['Private banking']:t.value==='financial_institution'?['Correspondent accounts']:['Bank account','Merchant account','Both bank and merchant accounts','Financing'];service.innerHTML=options(choices,choices.includes(service.value)?service.value:choices[0]);$('#referral-form [name=registration]').required=t.value!=='individual';$('#referral-form [name=registration]').closest('.field').hidden=t.value==='individual';};t.onchange=update;update();}
