formHandler('rate-form',f=>{const v=data(f);v.mode=v.mode==='Manual Override'?'manual':'auto';v.effective=v.effective+'Z';if(new Date(v.effective).toISOString()<store.now()&&v.effective.slice(0,19)===store.now().slice(0,19))v.effective=store.now();run(()=>store.changeRate(ui.adminIntro,v),'Prospective commercial rate saved. Historical commissions are unchanged.');});
const template=$('#agreement-form [name=template]');if(template){const load=()=>{$('#agreement-form [name=body]').value=M.AGREEMENT_DRAFTS[template.value];$('#agreement-form [name=category]').value=template.value==='Bespoke'?'Schedule':template.value;};template.onchange=load;if(!$('#agreement-form [name=body]').value)load();}
