formHandler('create-intro',f=>{const id=store.createIntroducer(data(f));ui.adminIntro=id;delete ui.drafts[draftKey()];save();render();notify('Invited account created. The referral link is inactive until agreement acceptance and Admin activation.');});
formHandler('clock-form',f=>run(()=>{const n=new Date(f.elements.clock.value+'Z').toISOString();if(n<store.now())throw Error('The review clock can only advance.');const before=store.now();store.s.clock=n;store.audit('Review clock advanced','REVIEW-TOOL',before,n);},'Sample clock advanced. Due commercial terms are now effective.'));
formHandler('provider-form',f=>{const v=data(f),overrides={};store.s.introducers.forEach(i=>{const k=v['override-'+i.id];if(k==='Allow')overrides[i.id]='allow';if(k==='Exclude')overrides[i.id]='exclude';});run(()=>store.updateProvider(ui.provider,{eligible:v.eligible==='Yes',reporting:v.reporting==='Yes',frequency:v.frequency,taxDefault:v.taxDefault,currency:v.currency,notes:v.notes,overrides}));});
