formHandler('commission-form',f=>{const rows=$$('[data-receipt]').filter(c=>f.elements['include-'+c.dataset.receipt].checked).map(c=>receiptValues(c.dataset.receipt));if(!rows.length)throw Error('Select at least one client allocation.');if(rows.some(r=>r.sourceRef!==rows[0].sourceRef||r.currency!==rows[0].currency||r.date!==rows[0].date))throw Error('Save one bank receipt per batch: same reference, date and currency for every line.');const ids=store.postProviderReceipt({provider:ui.provider,reference:rows[0].sourceRef,statementReference:f.elements.statementReference.value,date:rows[0].date,currency:rows[0].currency,amount:M.cents(f.elements.receiptTotal.value),confirmReceived:rows.every(r=>r.confirmReceived)},rows);delete ui.drafts[draftKey()];save();render();notify('Saved '+ids.join(', ')+'. Eligible statements updated; unresolved treatments are held. Notification previews are queued, not sent.');});
