const rk=$('[name=reportKind]');if(rk)rk.onchange=()=>{ui.reportKind=rk.value;ui.reportFilters={};render();save();};$$('[data-filter]').forEach(e=>e.onchange=()=>{ui.reportFilters||={};ui.reportFilters[e.dataset.filter]=e.value;render();save();});
