function perspective(p){if(!['admin','login'].includes(p)&&intro(p).status==='Terminated'){notify('This introducer account is terminated. Historical records remain available to SOPHIMA.',true);return;}capture();if(p==='admin'){role='admin';store.login('admin','SOPHIMA Admin');ui.view='overview';}else if(p==='login'){ui.view='login';}else{ui.intro=p;role='introducer';store.login('introducer',p);ui.view='dashboard';}save();render();window.scrollTo(0,0);}
async function action(a){if(a==='copy-link'){const txt='https://finsyndeo.com/apply/ref/'+intro(ui.intro).token;try{await navigator.clipboard.writeText(txt);notify('Referral link copied. It is an illustrative production URL.');}catch{notify('Copy the displayed referral link. This browser does not allow clipboard access.');}}
if(a==='client-path'){const u=new URL(location.href);u.search='?ref='+intro(ui.intro).token;window.open(u.href,'_blank','noopener');notify('Client-completed sample opened with attribution. Applicant sign-in is simulated.');}
if(a==='behalf-path')view('referral');
if(a==='future-receipt'){const n=store.s.entries.filter(e=>e.sourceRef.startsWith('FUTURE-DEMO')).length+1;run(()=>store.postReceipts([{relationship:'R1',period:'Future receipt '+n,date:date(store.now()),currency:'EUR',gross:100000,vat:0,treatment:'none',withholding:0,charges:0,received:100000,sourceRef:'FUTURE-DEMO-'+n,confirmReceived:true}]),'Future Cedar receipt posted at the current portfolio rate.');}
if(a==='sample-invoice-file'){const f=$('#invoice-form');let sum=0;store.s.entries.forEach(e=>{if(f.elements['sel-'+e.id]?.checked)sum+=M.cents(f.elements['amt-'+e.id].value);});download('sample-commission-invoice.txt',`ILLUSTRATIVE INVOICE ONLY\nInvoice number: ${f.elements.number.value||'SAMPLE-INV-001'}\nInvoice date: ${f.elements.date.value}\nCurrency: ${ui.currency}\nSubtotal: ${value(sum)}\nVAT: ${f.elements.vat.value}\nTotal: ${value(sum+M.cents(f.elements.vat.value))}`,'text/plain');notify('Upload the downloaded sample file to demonstrate portal-only invoicing.');}
if(a==='extract-invoice'){const file=$('#invoice-form [name=file]').files[0];if(!file)throw Error('Choose a sample invoice file first.');if(!file.name.endsWith('.txt'))throw Error('Extraction simulation supports the provided text sample. PDF/image OCR is a production integration, not connected here.');const text=await file.text(),pick=label=>new RegExp(label+':\\s*([^\\r\\n]+)','i').exec(text)?.[1]?.trim(),suggest={number:pick('Invoice number'),date:pick('Invoice date'),base:pick('Subtotal'),vat:pick('VAT'),total:pick('Total')};$('#extraction').hidden=false;$('#extraction').innerHTML=`<b>Extraction suggestions — review before using</b><p>${h(JSON.stringify(suggest,null,2))}</p><button type="button" id="apply-extraction">I reviewed these fields — apply to form</button><p>Text parsing demonstration only. Tax treatment and accounting approval remain manual.</p>`;$('#apply-extraction').onclick=()=>{const f=$('#invoice-form');Object.entries(suggest).forEach(([k,v])=>{if(v&&f.elements[k])f.elements[k].value=v;});capture();save();notify('Reviewed suggestions copied. Allocations and totals must still reconcile.');};}
if(a==='export-report'){store.admin();const r=reportData();download('FinSyndeo-'+ui.reportKind+'.csv','\uFEFF'+csv([r.heads,...r.rows]));}
if(a==='export-audit'){store.admin();download('FinSyndeo-audit.csv','\uFEFF'+csv([['Time','Actor','Record','Event','Previous','New'],...store.s.audit.map(a=>[a.at,a.actor,a.record,a.event,JSON.stringify(a.before),JSON.stringify(a.after)])]));}
if(a==='export-intro'){const x=store.external(ui.intro);download('My-FinSyndeo-commission-statement.csv','\uFEFF'+csv([['Entry','Client','Provider code','Period','Currency','Net','Rate (%)','My commission'],...x.entries.map(e=>[e.id,client(e.client),e.provider,e.period,e.currency,value(e.net),e.rate/100,value(e.payable)])]));}}
document.addEventListener('invalid',e=>{e.target.setAttribute('aria-invalid','true');const label=e.target.closest('label')?.querySelector('span')?.textContent||e.target.name;notify('Please check '+label+': '+e.target.validationMessage,true);},true);
document.addEventListener('input',e=>e.target.removeAttribute('aria-invalid'));
document.querySelectorAll('.review-bar [data-perspective]').forEach(b=>b.onclick=()=>perspective(b.dataset.perspective));$('#reset').onclick=()=>{if(!confirm('Reset only this Introducer Module sample? Uploaded sample files and changes will be removed. Existing FinSyndeo drafts are unaffected.'))return;store.s=M.seed();Object.assign(ui,{view:'dashboard',intro:'I-A',adminIntro:'I-A',provider:'FS-003',currency:'EUR',drafts:{},invoiceId:null,reportFilters:{},reportKind:'Incoming provider commissions'});role='introducer';store.login('introducer','I-A');save();render();};
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const n=JSON.parse(e.newValue);if(n.state.seq>store.s.seq){capture();store.s=n.state;render();notify('Sample records updated in another review tab. Your current form values are retained.');}}catch{}});
// Admin records imported signatures and external derivatives separately from introducer acceptance.
const reviewedProfile=profilePage;profilePage=function(){const ds=store.s.documents.filter(d=>d.owner===ui.adminIntro),contracts=ds.filter(d=>['Agreement','Schedule','Addendum'].includes(d.category)),originals=ds.filter(d=>d.classification==='internal-original');return reviewedProfile()+`<details class="panel"><summary>Import signed agreement evidence — separate Admin action</summary><p class="hint">Demonstration only. Record the actual parties; this never signs as the introducer.</p><form id="signed-evidence-form"><label class="field"><span>Agreement version</span><select name="document">${contracts.map(d=>`<option value="${h(d.id)}">${h(d.name)} · ${h(d.version)}</option>`).join('')}</select></label><div class="grid">${field('Actual introducer signatory','introducerSignatory','text','',true)}${field('Actual SOPHIMA signatory','sophimaSignatory','text','',true)}${field('Signed date','signedDate','date',date(store.now()),true)}</div><label class="field"><span>Signed evidence — restricted original</span><input name="file" type="file" required></label><button>Record imported signature evidence</button></form></details><details class="panel"><summary>Approve a separate redacted external copy</summary><form id="derivative-form"><label class="field"><span>Internal original</span><select name="original">${originals.map(d=>`<option value="${h(d.id)}">${h(d.name)}</option>`).join('')}</select></label><label class="field"><span>Redacted copy for this introducer</span><input name="file" type="file" required></label>${field('Disclosure / redaction review reason','reviewReason','text','',true)}<button ${!originals.length?'disabled':''}>Approve external derivative</button></form><p class="hint">Internal originals and external copies are separate records. Remove provider identity, unrelated transactions and third-party personal details before approving the copy.</p></details>`;};
const reviewedReferrals=adminReferralsPage;adminReferralsPage=function(){return reviewedReferrals()+`<details class="panel"><summary>Record first financing disbursement</summary><form id="disbursement-form"><label class="field"><span>Activated financing relationship</span><select name="relationship">${store.s.relationships.filter(r=>r.service==='Financing'&&r.activated&&!r.disbursement).map(r=>`<option value="${h(r.id)}">${h(r.id)} · ${h(client(r.client))}</option>`).join('')}</select></label><div class="grid">${field('Disbursement date','date','date',date(store.now()),true)}${field('Amount disbursed','amount','number','',true,'min="0.01" step="0.01"')}${select('Currency','currency',['EUR','GBP','USD','CHF'],'EUR')}${field('Provider / settlement evidence reference','reference','text','',true)}</div>${check('I have reviewed the first disbursement evidence (demo only).','verified')}<button>Record qualifying disbursement</button></form><p class="hint">An offer or an active undrawn facility does not qualify a successful financing client.</p></details>`;};
const reviewedBind=bind;bind=function(){reviewedBind();formHandler('signed-evidence-form',async f=>{const v=data(f),document=store.s.documents.find(d=>d.id===v.document);if(!document)throw Error('Select an agreement version.');const evidenceDocument=await fileDoc(f.elements.file,ui.adminIntro,'Signed evidence');store.importAgreementEvidence(v.document,{...v,evidenceDocument,documentFingerprint:M.fingerprint(document.body)});save();render();notify('Separate signature evidence import recorded in this demonstration.');});formHandler('derivative-form',async f=>{const v=data(f);if(!v.original||!v.reviewReason?.trim())throw Error('Select the original and provide a disclosure review reason.');const id=await fileDoc(f.elements.file,ui.adminIntro,'External derivative'),d=store.s.documents.find(d=>d.id===id);store.addDoc({...d,id:undefined,classification:'approved-derivative',original:v.original,reviewReason:v.reviewReason,status:'Approved external copy'});save();render();notify('Separate reviewed external copy is available to this introducer.');});formHandler('disbursement-form',f=>{const v=data(f);run(()=>store.recordFinancingDisbursement(v.relationship,{...v,amount:M.cents(v.amount)}),'First verified disbursement recorded; distinct-client qualification updated.');});};

window.addEventListener('pagehide',()=>{capture();save();});render();

window.IntroducerReview={store,ui,perspective,view,save};
